1	export interface Scenario {
2	  customer: { yearsWithMHPCO: number };
3	  steps: Step[];
4	}
5	
6	export type Step = QuoteStep | ClaimStep;
7	
8	export interface QuoteStep {
9	  op: "quote";
10	  items: Item[];
11	}
12	
13	export interface Item {
14	  type: string;
15	  material?: string;
16	  enchantment?: number;
17	  cursed?: boolean;
18	}
19	
20	export interface ClaimStep {
21	  op: "claim";
22	  policy: number;
23	  incident: Incident;
24	}
25	
26	export interface Incident {
27	  cause: string;
28	  damages: Damage[];
29	}
30	
31	export interface Damage {
32	  itemType: string;
33	  amount: number;
34	}
35	
36	export type Result = { premium: number } | { payout: number; remainingCap: number };
37	
38	const PROCESSING_FEE = 5;
39	
40	const FIRST_INSURANCE_SURCHARGE = 0.1;
41	
42	/** Rounds up in the MHPCO's favor, ignoring binary floating-point noise. */
43	const roundPremium = (amount: number): number => Math.ceil(Number(amount.toFixed(6)));
44	
45	const BASE_PREMIUMS: Record<string, number> = {
46	  sword: 100,
47	  amulet: 60,
48	};
49	
50	const quotePremium = (items: Item[]): number => {
51	  const basePremium = items.reduce((sum, item) => sum + BASE_PREMIUMS[item.type], 0);
52	  return roundPremium(basePremium * (1 + FIRST_INSURANCE_SURCHARGE) + PROCESSING_FEE);
53	};
54	
55	const runStep = (step: Step): Result => {
56	  if (step.op === "quote") return { premium: quotePremium(step.items) };
57	  throw new Error(`Unsupported step: ${step.op}`);
58	};
59	
60	export const runScenario = (scenario: Scenario): { results: Result[] } => {
61	  return { results: scenario.steps.map(runStep) };
62	};
