const quotePremium = (items: Item[]): number => {
  const basePremium = items.reduce((sum, item) => sum + BASE_PREMIUMS[item.type], 0);
  const firstInsuranceSurcharge = basePremium * FIRST_INSURANCE_SURCHARGE;
  return roundPremium(basePremium + firstInsuranceSurcharge + PROCESSING_FEE);
};
